--
-- Table structure for table `evaluations`
--

DROP TABLE IF EXISTS `evaluations`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `evaluations` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `patient_id` bigint unsigned NOT NULL,
  `medico_referencia` text COLLATE utf8mb4_unicode_ci,
  `centro_referencia` text COLLATE utf8mb4_unicode_ci,
  `diagnostico_medico` text COLLATE utf8mb4_unicode_ci,
  `diagnostico_medico_otro` text COLLATE utf8mb4_unicode_ci,
  `responsable_evaluacion` int DEFAULT NULL,
  `costo_evaluacion` decimal(10,2) DEFAULT NULL,
  `motivo_consulta` text COLLATE utf8mb4_unicode_ci,
  `historia_enfermedad_actual` longtext COLLATE utf8mb4_unicode_ci,
  `frecuencia_cardiaca` int DEFAULT NULL,
  `frecuencia_respiratoria` int DEFAULT NULL,
  `presion_arterial` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `temperatura` decimal(4,1) DEFAULT NULL,
  `caracteristicas_dolor` text COLLATE utf8mb4_unicode_ci,
  `inspeccion` text COLLATE utf8mb4_unicode_ci,
  `evaluacion_postural` text COLLATE utf8mb4_unicode_ci,
  `contractura_muscular` text COLLATE utf8mb4_unicode_ci,
  `puntos_dolorosos` text COLLATE utf8mb4_unicode_ci,
  `puntos_gatillo` text COLLATE utf8mb4_unicode_ci,
  `retreaccion_acortamiento` text COLLATE utf8mb4_unicode_ci,
  `tono` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `tono_detalle` text COLLATE utf8mb4_unicode_ci,
  `trofismo` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `trofismo_detalle` text COLLATE utf8mb4_unicode_ci,
  `evaluacion_marcha` text COLLATE utf8mb4_unicode_ci,
  `balance_articular` text COLLATE utf8mb4_unicode_ci,
  `balance_muscular` text COLLATE utf8mb4_unicode_ci,
  `sensibilidad` text COLLATE utf8mb4_unicode_ci,
  `examenes_complementarios` text COLLATE utf8mb4_unicode_ci,
  `diagnostico_kinesico` text COLLATE utf8mb4_unicode_ci,
  `objetivos_tratamiento` text COLLATE utf8mb4_unicode_ci,
  `plan_tratamiento` text COLLATE utf8mb4_unicode_ci,
  `fecha` date DEFAULT NULL,
  `estado` text COLLATE utf8mb4_unicode_ci,
  `created_by` bigint unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `evaluations_patient_id_foreign` (`patient_id`),
  CONSTRAINT `evaluations_patient_id_foreign` FOREIGN KEY (`patient_id`) REFERENCES `patients` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=405 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

