INSERT INTO `evaluations` VALUES (1,1,NULL,NULL,'Post reparación de manguito rotador',NULL,2,12.50,'Disminución de movilidad en la movilidad de hombro y fuerza miembros superior derecho post cirugía ruptura de manguito rotador.','Paciente refiere ser intervenida por ruptura de manguito rotador en mayo del 2025, ingresa al servicio de Fisioterapia en agosto del 2025, en septiembre de la misma gestión se da continuidad al tratamiento.',60,20,'110/70',36.0,'dolor de tipo opresivo en los últimos grados de flexión. abducción, extensión y rotaciones de hombro derecho.\r\n7/10 EVA\r\nAlivia con el reposo.','Se evidencia a la observación presencia de cicatriz de aproximadamente 10 centímetros en la región anterior de hombro.','Se evidencia en plano frontal anterior y posterior asimetría de hombros descenso de hombro izquierdo.','a nivel de trapecio superior bilateral de predominio derecho.','a nivel de trapecio superior bilateral de predominio derecho.','a nivel de trapecio superior bilateral de predominio derecho.','De pectorales bilateral de predominio derecho.','Normal','no refiere','Hipotrofia','Disminuido en region de brazo derecho en comparacion ala brazo izquierdo en 1,5 cm','No refiere','flexion 150°\r\nextension 45°\r\nabduccion 150°\r\nrotacion interna 45°\r\nrotacion externa 45°','flexion -4/5\r\nextension -4/5\r\nabducion -4/5\r\nrotacion interna -4/5\r\nrotacion externa -4/5','conservada','Test de Jove (+) derecho\r\nTest de Rascado de Apley (+) derecho\r\nTest de Yergazon (-) derecho','Deficit funcional y estructural de articulacion glenohumeral con limitación moderada para la flexión, extensión, abducción, rotación interna y externa de hombro con restricción para las actividades de la vida diaria básicas y complejas.','Disminuir el dolor\r\nincrementar rangos de movimiento\r\nmejorar la elasticidad muscular\r\nfortalecer musculatura periarticular de hombro','Magnetoterapia\r\nTermoterapia\r\nTerapia Manual\r\nkinesioterpia activo- asistida\r\nkinesioterapia activo resistida','2025-12-08','ALTA',2,'2025-12-09 11:25:28','2026-05-03 17:41:27'),(2,2,NULL,NULL,'Tendinitis',NULL,2,25.00,'Dolor de rodillas bilateral de predominio derecho','Paciente refiere que hace 3 semanas inicia el dolor a nivel de la articulación de rodillas anterior de predominio derecho al realizar su actividad deportiva (salto basquetbol)',60,18,'120/80',36.5,'Dolor punzante a nivel inferior de la rotula sobre todo en descarga de peso (saltos) 6/10 EVA','No se evidencia asimetrías, aumento de volumen de la articulación, hematomas ni nada de relevancia.','No se evidencia anomalías posturales','no refiere','a nivel del tendón rotuliano bilateral de predominio derecho','no refiere','De isquitibiales, aductores bilateral de predominio derecho.','Normal','sin alteración segmentaria','Normal','sin alteración segmentaria','Disminución de longitud de paso derecho, marcha de tipo claudicante.','Flexión 165°\r\nextensión 0°','Cuadriceps -4/5\r\nAductores -4/5\r\nAbductores 5/5\r\nIsquitibiales -4/5','Sin alteracion','Prueba de Cajon anterior (-) der; (-) izq\r\nPrueba de Cajon posterior (-) der; (-) izq\r\nManiobra forzada en valgo (-) der; (-) izq\r\nManiobra forzada en varo (-) der; (-) izq\r\nEcografia de partes blandas \r\ndx. tendinitis rotuliana bilateral.','Déficit funcional y estructural de articulación de rodilla, tendones rotulianos con limitación moderada para realizar saltos, bipedestación prolongada, marcha extensa; restricción de tipo deportivo.','Disminuir el dolor e inflamación.\r\nRequilibrar musculatura periarticular, articulación de rodillas.\r\nfortalecer musculatura de miembros inferiores\r\nelongar cadena muscular posterior e interna.','Ultrasonido Pulsátil a nivel de ambos tendones técnica semiestacionaria Fr. cabezal 3 Mhz, tiempo 7 min por tendón.\r\nMagnetoterapia programa regenracion\r\nelectrofortaleciento en cuadriceps\r\nkinesioterapia activa\r\nkinesioterapia activa resistida\r\ncircuitos de propiocepcion.','2025-10-08','ALTA',2,'2025-12-11 08:35:56','2025-12-11 09:14:53'),(3,3,NULL,NULL,'Tendinitis',NULL,2,25.00,'Dolor en la muñeca región radial.','Paciente refiere que sufre una lesión a nivel del tendón del abductor largo y extensor corto del ´pulgar en el mes de agosto (dx. tendinitis de D Quervain)no realiza sesiones de fisioterapia solo es tratado por su medico con analgésicos en pastillas y tópicos. actualmente refiere sentir dolor en la  misma región después de tocar su instrumento musical (Clarinete) y levantar pesos.',60,18,'120/80',36.5,'Dolor tipo lancinante a nivel del abductor largo y extensor corto del pulgar, en movimientos de pronosupinación de mano con peso \r\n8/10 EVA','Nada de relevancia.','sin alteración postural','no refiere','a nivel de la apófisis estiloides del radio y tabaquera anatómica.','no refiere','no refiere','Normal','sin alteración','Normal','sin alteración','sin alteración','extensión 70°\r\nflexión 45°\r\npronación 85°\r\nsupinación 85°  \r\ninclinación radial 20°\r\ninclinación cubital 30°','flexor superficial común +4/5 \r\nflexor superficial profundo +4/5 \r\nextensor corto del pulgar -4/5\r\nabductor largo del pulgar -4/5','conservada','Prueba Finkelstein (+) izquierdo\r\nTest de Phallen (-) izquierdo','Déficit funcional y estructural del abductor largo y extensor corto del pulgar izquierdo con limitación moderada para los movimientos de oposición del pulgar pinza fina, esférica y cilíndrica; con restricción de tipo socioeconómico.','Disminuir el dolor e inflamación.\r\nincrementar fuerza muscular\r\nentrenar pinzas, fina, gruesa, esférica y cilíndrica.','Magnetoterapia\r\nUltrasonido pulsátil\r\nTermoterapia por conducción\r\nKinesioterapia activa','2025-12-04','ALTA',2,'2025-12-11 14:33:10','2025-12-11 14:40:59'),(4,4,NULL,'Unicent','Tendinitis',NULL,2,25.00,'Tendinosis del supraespinoso y subescapular izquierda','paciente refiere sentir dolor a nivel de hombro izquierdo hace cuatro meses atrás al momento de elevar su hombro y recostarse sobre lado, acude a sesiones de fisioterapia en la Universidad Central y por cierre de gestión, acude al servicio para continuar con sesiones de fisioterapia.',70,20,'120/80',36.5,'dolor de tipo punzante a nivel de la articulación glenumeral izquierda en últimos grados de movimiento de flexión, abducción y rotación interna de hombro 7/10 EVA','No se evidencia nada de relevancia','se evidencia en plano frontal anterior, posterior. elevación, antepulsión de hombro izquierdo.\r\nplano sagital/ anteriorización cervical.','a nivel de trapecio superior bilateral','a nivel de trapecio superior bilateral.\r\na nivel de redondo menor.','a nivel de trapecio superior bilateral.\r\na nivel de redondo menor.','pectoral mayor bilateral de predominio izquierdo','Normal','sin alteración','Normal','sin alteración','sin alteración','flexión  100°\r\nextensión 35°\r\nabducción 90°\r\nrotación interna 30°\r\nrotación externa 30°','deltoides anterior 3/5\r\ndeltoides medio 3/5\r\ndeltoides posterior 3/5','conservada','Prueba de Jove (+) izquierdo\r\nPrueba de abducción de hombro (+) izquierdo\r\nprueba de Patte (+) izquierdo','Déficit funcional y estructural del tendón del musculo supraespinoso y subescapular con limitación moderada a los movimientos de flexión, extensión, abducción,  rotación interna restricción  en las AVDs, básicas y complejas complejas y reacretivas.','disminuir el dolor e inflamación\r\nganar rango articular\r\n fortalecer musculatura de manguito rotador','Magnetoterapia\r\nultrasonido\r\nterapia manual\r\ntermoterapia\r\nkinesioterapia activa asistida.','2025-11-26','ALTA',2,'2025-12-11 15:11:42','2025-12-11 15:49:54'),(5,5,NULL,NULL,'Cervicalgia',NULL,2,25.00,'Dolor a nivel cervical y dorsal.','Paciente refiere que existe dolor a nivel cervicodorsal de predominio derecho, hace aproximadamente un mes sin presencia de cefaleas, migrañas o insomnio.',70,18,'120/80',36.5,'Dolor de tipo opresivo a la palpación, a nivel de trapecios superiores, medios bilateral de predominio derecho